TOC.FLDID9, TOC.FLDTAG9, TOC.FLDTAGA9, GENHTAB_9.FLDTAB AS FLDTAB9, GENHTAB_9.FLDCOM AS FLDCOM9, GENHTAB_9.FLDCOMA AS FLDCOMA9, GENHTAB_9.FLDDFORMAT AS FLDDFORMAT9, GENHTAB_9.FLDIFORMAT AS FLDIFORMAT9, GENHTAB_9.FLDTYPE AS FLDTYPE9, GENHTAB_9.SUBLINKF AS SUBLINKF9,  GENHTAB_9.FLDSEARCH AS FLDSEARCH9, GENHTAB_9.FLDCRITERIA AS FLDCRITERIA9, GENHTAB_9.FLDCHGINF as FLDCHGINF9, GENHTAB_9.FLDLOWER as FLDLOWER9, GENHTAB_9.FLDUPPER as FLDUPPER9, GENHTAB_9.FLDREGEX as FLDREGEX9, GENHTAB_9.FLDFUNC as FLDFUNC9, GENHTAB_9.FLDMAP as FLDMAP9, CASE WHEN GENHTAB_9.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF9, GENHTAB_9.SACCREG as SACCREG9,  
TOC.FLDID10, TOC.FLDTAG10, TOC.FLDTAGA10, GENHTAB_10.FLDTAB AS FLDTAB10, GENHTAB_10.FLDCOM AS FLDCOM10, GENHTAB_10.FLDCOMA AS FLDCOMA10, GENHTAB_10.FLDDFORMAT AS FLDDFORMAT10, GENHTAB_10.FLDIFORMAT AS FLDIFORMAT10, GENHTAB_10.FLDTYPE AS FLDTYPE10, GENHTAB_10.SUBLINKF AS SUBLINKF10,  GENHTAB_10.FLDSEARCH AS FLDSEARCH10, GENHTAB_10.FLDCRITERIA AS FLDCRITERIA10, GENHTAB_10.FLDCHGINF as FLDCHGINF10, GENHTAB_10.FLDLOWER as FLDLOWER10, GENHTAB_10.FLDUPPER as FLDUPPER10, GENHTAB_10.FLDREGEX as FLDREGEX10, GENHTAB_10.FLDFUNC as FLDFUNC10, GENHTAB_10.FLDMAP as FLDMAP10, CASE WHEN GENHTAB_10.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF10, GENHTAB_10.SACCREG as SACCREG10,  
