TOC.FLDID13, TOC.FLDTAG13, TOC.FLDTAGA13, GENHTAB_13.FLDTAB AS FLDTAB13, GENHTAB_13.FLDCOM AS FLDCOM13, GENHTAB_13.FLDCOMA AS FLDCOMA13, GENHTAB_13.FLDDFORMAT AS FLDDFORMAT13, GENHTAB_13.FLDIFORMAT AS FLDIFORMAT13, GENHTAB_13.FLDTYPE AS FLDTYPE13, GENHTAB_13.SUBLINKF AS SUBLINKF13,  GENHTAB_13.FLDSEARCH AS FLDSEARCH13, GENHTAB_13.FLDCRITERIA AS FLDCRITERIA13, GENHTAB_13.FLDCHGINF as FLDCHGINF13, GENHTAB_13.FLDLOWER as FLDLOWER13, GENHTAB_13.FLDUPPER as FLDUPPER13, GENHTAB_13.FLDREGEX as FLDREGEX13, GENHTAB_13.FLDFUNC as FLDFUNC13, GENHTAB_13.FLDMAP as FLDMAP13, CASE WHEN GENHTAB_13.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF13, GENHTAB_13.SACCREG as SACCREG13,  
TOC.FLDID14, TOC.FLDTAG14, TOC.FLDTAGA14, GENHTAB_14.FLDTAB AS FLDTAB14, GENHTAB_14.FLDCOM AS FLDCOM14, GENHTAB_14.FLDCOMA AS FLDCOMA14, GENHTAB_14.FLDDFORMAT AS FLDDFORMAT14, GENHTAB_14.FLDIFORMAT AS FLDIFORMAT14, GENHTAB_14.FLDTYPE AS FLDTYPE14, GENHTAB_14.SUBLINKF AS SUBLINKF14,  GENHTAB_14.FLDSEARCH AS FLDSEARCH14, GENHTAB_14.FLDCRITERIA AS FLDCRITERIA14, GENHTAB_14.FLDCHGINF as FLDCHGINF14, GENHTAB_14.FLDLOWER as FLDLOWER14, GENHTAB_14.FLDUPPER as FLDUPPER14, GENHTAB_14.FLDREGEX as FLDREGEX14, GENHTAB_14.FLDFUNC as FLDFUNC14, GENHTAB_14.FLDMAP as FLDMAP14, CASE WHEN GENHTAB_14.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF14, GENHTAB_14.SACCREG as SACCREG14,  
