FROM      
 TOC INNER JOIN SCHEME_MASTER ON TOC.TOC = SCHEME_MASTER.TOC     
OUTER APPLY (SELECT * FROM FN_GENHTAB(TOC.FLDID1, @P_SEGMENT,TOC.FLDID1)) AS GENHTAB_1  
